fn main() -> Void {
    let total: Int = 0;
    let throughA: Int = 0;
    let throughB: Int = 0;
    let throughC: Int = 0;
    let throughD: Int = 0;

    loop m1 in 0..2 {
        let p1: Int = m1;
        loop m2 in 0..2 {
            let p2: Int = p1 + m2;
            if p2 < 0 || p2 > 3 {
                continue;
            }
            loop m3 in 0..2 {
                let p3: Int = p2 + m3;
                if p3 < 0 || p3 > 3 {
                    continue;
                }
                if p3 == 3 {
                    total = total + 1;
                    if 0 == 0 || p1 == 0 || p2 == 0 || p3 == 0 {
                        throughA = throughA + 1;
                    }
                    if p1 == 1 || p2 == 1 || p3 == 1 {
                        throughB = throughB + 1;
                    }
                    if p1 == 2 || p2 == 2 || p3 == 2 {
                        throughC = throughC + 1;
                    }
                    if p1 == 3 || p2 == 3 || p3 == 3 {
                        throughD = throughD + 1;
                    }
                }
            }
        }
    }

    fx {
        println("Total routes: ", total);
        println("Through A: ", throughA);
        println("Through B: ", throughB);
        println("Through C: ", throughC);
        println("Through D: ", throughD);
    }
    ret;
}

fn maxContiguous(row: Int[]) -> Int {
    let best: Int = row[0];
    let cur: Int = row[0];
    loop i in 1..length(row) {
        cur = cur + row[i];
        if cur < row[i] {
            cur = row[i];
        }
        if cur > best {
            best = cur;
        }
    }
    ret best;
}

