fn main() -> Void {
    let names: Text[] = ["Ana", "Ben", "Cara", "Diego", "Eva"];
    let tips: Real[][] = [
        [12.50, 15.00, 11.25, 14.75],
        [10.00, 13.50, 12.00, 16.25],
        [14.25, 11.00, 15.50, 13.75],
        [9.75, 12.25, 14.00, 10.50],
        [13.00, 16.50, 12.75, 15.25]
    ];

    let grandTotal: Real = 0.0;
    let abovePool: Int = 0;
    let staffCount: Int = length(names);

    let totals: Real[] = [];
    loop i in 0..staffCount {
        let t: Real = 0.0;
        loop j in 0..length(tips[i]) {
            t = t + tips[i][j];
        }
        totals = totals + [t];
        grandTotal = grandTotal + t;
    }

    let poolAvg: Real = grandTotal / staffCount;

    loop i in 0..staffCount {
        if totals[i] > poolAvg {
            abovePool = abovePool + 1;
        }
    }

    fx {
        loop i in 0..staffCount {
            let avg: Real = totals[i] / 4.0;
            println(names[i], " total=", format_float(totals[i], 2), " avg=", format_float(avg, 2));
        }
        println("Pool average: ", format_float(poolAvg, 2));
        println("Above pool: ", abovePool);
    }
    ret;
}

