fn main() -> Void {
    let flat: Int[] = [5, 1, 2, 1, 5, 5, 1, 2, 1, 2, 5, 1, 2, 5, 1, 1];
    let grid: Int[][] = [];
    loop r in 0..4 {
        let row: Int[] = [];
        loop c in 0..4 {
            row = row + [flat[r * 4 + c]];
        }
        grid = grid + [row];
    }

    loop r in 0..4 {
        loop c in 0..4 {
            if grid[r][c] == 5 {
                grid[r][c] = 0;
            } else {
                let doubled: Int = grid[r][c] * 2;
                if doubled > 4 {
                    grid[r][c] = 4;
                } else {
                    grid[r][c] = doubled;
                }
            }
        }
    }

    let total: Int = 0;
    loop r in 0..4 {
        loop c in 0..4 {
            total = total + grid[r][c];
        }
    }

    let colSums: Int[] = [0, 0, 0, 0];
    loop c in 0..4 {
        loop r in 0..4 {
            colSums[c] = colSums[c] + grid[r][c];
        }
    }

    let maxIdx: Int = 0;
    loop c in 1..4 {
        if colSums[c] > colSums[maxIdx] {
            maxIdx = c;
        }
    }

    fx {
        println("Total: ", total);
        println("Col0: ", colSums[0]);
        println("Col1: ", colSums[1]);
        println("Col2: ", colSums[2]);
        println("Col3: ", colSums[3]);
        println("MaxCol: ", maxIdx);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [];
    loop r in 0..5 {
        let row: Int[] = [];
        loop c in 0..5 {
            if r == 2 && c == 2 {
                row = row + [1];
            } else {
                row = row + [0];
            }
        }
        grid = grid + [row];
    }

    loop round in 0..3 {
        let next: Int[][] = [];
        loop r in 0..5 {
            let row: Int[] = [];
            loop c in 0..5 {
                let wet: Bool = grid[r][c] == 1;
                if !wet {
                    if r > 0 && grid[r - 1][c] == 1 {
                        wet = true;
                    }
                    if r < 4 && grid[r + 1][c] == 1 {
                        wet = true;
                    }
                    if c > 0 && grid[r][c - 1] == 1 {
                        wet = true;
                    }
                    if c < 4 && grid[r][c + 1] == 1 {
                        wet = true;
                    }
                }
                if wet {
                    row = row + [1];
                } else {
                    row = row + [0];
                }
            }
            next = next + [row];
        }
        grid = next;
    }

    let wetCount: Int = 0;
    loop r in 0..5 {
        loop c in 0..5 {
            if grid[r][c] == 1 {
                wetCount = wetCount + 1;
            }
        }
    }
    let dryCount: Int = 25 - wetCount;

    let corners: Int = 0;
    if grid[0][0] == 1 {
        corners = corners + 1;
    }
    if grid[0][4] == 1 {
        corners = corners + 1;
    }
    if grid[4][0] == 1 {
        corners = corners + 1;
    }
    if grid[4][4] == 1 {
        corners = corners + 1;
    }

    fx {
        println("Wet: ", wetCount);
        println("Dry: ", dryCount);
        println("Corners: ", corners);
    }
    ret;
}

