@pure
fn octal_to_decimal(s: Text) -> Int {
    let result: Int = 0;
    loop ch in s {
        let d: Int = ord(ch) - ord("0");
        result = result * 8 + d;
    }
    ret result;
}

@pure
fn is_perfect_square(n: Int) -> Bool {
    if n < 0 {
        ret false;
    }
    let r: Int = int(sqrt(real(n)));
    if r * r == n {
        ret true;
    }
    let r2: Int = r + 1;
    if r2 * r2 == n {
        ret true;
    }
    ret false;
}

fn main() -> Void {
    let bundles: Text[] = ["14", "27", "64", "100", "121", "31", "52"];
    let count: Int = 0;
    loop b in bundles {
        let dec: Int = octal_to_decimal(b);
        let sq: Bool = is_perfect_square(dec);
        if sq {
            count = count + 1;
        }
        let label: Text = if sq { "Yes" } else { "No" };
        fx {
            println("Octal ", b, " -> Decimal ", dec, " Square=", label);
        }
    }
    fx {
        println("Perfect squares: ", count);
    }
    ret;
}

fn main() -> Void {
    let isbns: Text[] = ["1234567890", "0987654321", "1111111111", "5432109876", "2468135790"];
    let validCount: Int = 0;

    loop isbn in isbns {
        let sum: Int = 0;
        let alt: Int = 0;
        let n: Int = string_len(isbn);
        loop i in 0..n {
            let ch: Text = isbn[i];
            let d: Int = ord(ch) - ord("0");
            sum = sum + d;
            if i % 2 == 0 {
                alt = alt + d;
            } else {
                alt = alt - d;
            }
        }
        let r1: Int = sum % 11;
        let r2: Int = alt % 11;
        if r2 < 0 {
            r2 = r2 + 11;
        }
        let valid: Bool = (r1 == r2) && (r1 != 0);
        if valid {
            validCount = validCount + 1;
        }
        let validText: Text = if valid { "Yes" } else { "No" };
        fx {
            println("ISBN ", isbn, ": Mod11=", r1, " Alt=", r2, " Valid=", validText);
        }
    }

    fx {
        println("Valid books: ", validCount);
    }
    ret;
}

@pure
fn isPrime(n: Int) -> Bool {
    if n < 2 {
        ret false;
    }
    if n == 2 {
        ret true;
    }
    if n % 2 == 0 {
        ret false;
    }
    let i: Int = 3;
    loop i * i <= n {
        if n % i == 0 {
            ret false;
        }
        i = i + 2;
    }
    ret true;
}

@pure
fn countDivisors(n: Int) -> Int {
    let count: Int = 0;
    loop i in 1..n + 1 {
        if n % i == 0 {
            count = count + 1;
        }
    }
    ret count;
}

fn main() -> Void {
    let cycles: Int[] = [11, 17, 24, 29, 36, 41, 47, 54];
    let primeCount: Int = 0;
    let mod9Count: Int = 0;

    loop c in cycles {
        let prime: Bool = isPrime(c);
        let divs: Int = countDivisors(c);
        let mod9: Bool = c % 9 == 0;
        let primeStr: Text = if prime { "Yes" } else { "No" };
        let mod9Str: Text = if mod9 { "Yes" } else { "No" };
        if prime {
            primeCount = primeCount + 1;
        }
        if mod9 {
            mod9Count = mod9Count + 1;
        }
        fx {
            println("Cycle ", c, ": Prime=", primeStr, " Divisors=", divs, " Mod9Zero=", mod9Str);
        }
    }

    fx {
        println("Prime cycles: ", primeCount, " | Mod9 zero cycles: ", mod9Count);
    }
    ret;
}

@pure
fn hex_to_dec(hex: Text) -> Int {
    let value: Int = 0;
    loop ch in hex {
        let digit: Int = 0;
        if ch >= "0" && ch <= "9" {
            digit = ord(ch) - ord("0");
        } else if ch >= "A" && ch <= "F" {
            digit = ord(ch) - ord("A") + 10;
        } else if ch >= "a" && ch <= "f" {
            digit = ord(ch) - ord("a") + 10;
        }
        value = value * 16 + digit;
    }
    ret value;
}

@pure
fn dec_to_bin(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let bits: Text = "";
    let v: Int = n;
    loop {
        let bit: Int = v % 2;
        bits = int_to_text(bit) + bits;
        v = v div 2;
        if v == 0 {
            break;
        }
    }
    ret bits;
}

