        let n: Int = nums[i];
        let d: Int = dens[i];
        let g: Int = gcd(n, d);
        let rn: Int = n div g;
        let rd: Int = d div g;
        let whole: Text = if rd == 1 { "Yes" } else { "No" };
        if rd == 1 {
            wholeCount = wholeCount + 1;
        }
        fx {
            println("Flow ", n, "/", d, " -> Reduced ", rn, "/", rd, " Whole=", whole);
        }
    }

    fx {
        println("Whole number flows: ", wholeCount);
    }
    ret;
}

fn normalize(name: Text) -> Text {
    let out: Text = "";
    let startOfWord: Bool = true;
    loop ch in name {
        if ch == "-" || ch == "'" {
            out = out + ch;
            startOfWord = true;
        } else {
            if startOfWord {
                out = out + upper(ch);
                startOfWord = false;
            } else {
                out = out + lower(ch);
            }
        }
    }
    ret out;
}

