@pure
fn titleCaseWord(w: Text) -> Text {
    if string_len(w) == 0 {
        ret "";
    }
    let first: Text = w[0..1];
    let rest: Text = w[1..];
    ret upper(first) + lower(rest);
}

@pure
fn titleCase(s: Text) -> Text {
    let parts: Text[] = split(s, " ");
    let out: Text[] = [];
    loop p in parts {
        out = out + [titleCaseWord(p)];
    }
    ret join(out, " ");
}

