fn main() -> Void {
    let stationKm: Int[] = [5, 10, 15, 20];
    let cups: Int[] = [2, 3, 1, 2];
    let runners: Int[] = [6, 11, 4, 16, 9, 21, 14, 7, 19, 3, 12, 18];

    let served: Int = 0;
    let turnedAway: Int = 0;

    loop r in 0..length(runners) {
        let km: Int = runners[r];
        let best: Int = -1;
        loop s in 0..length(stationKm) {
            if stationKm[s] <= km {
                if best == -1 {
                    best = s;
                } else {
                    if km - stationKm[s] < km - stationKm[best] {
                        best = s;
                    }
                }
            }
        }
        if best == -1 {
            turnedAway = turnedAway + 1;
        } else {
            if cups[best] > 0 {
                cups[best] = cups[best] - 1;
                served = served + 1;
            } else {
                turnedAway = turnedAway + 1;
            }
        }
    }

    let remaining: Int = 0;
    loop s in 0..length(cups) {
        remaining = remaining + cups[s];
    }

    fx {
        println("ServedRunners=", served);
        println("TurnedAway=", turnedAway);
        println("CupsRemaining=", remaining);
    }
    ret;
}

fn main() -> Void {
    let pref: Int[] = [0, 1, 2, 0, 1, 2, 0, 1, 2];
    let dur: Int[] = [30, 45, 20, 35, 25, 40, 15, 50, 10];
    let n: Int = 9;

    // freeAt[d] = time when dryer d becomes free (0 = free now)
    let freeAt: Int[] = [0, 0, 0];
    // startAt[i] = time when load i starts, -1 if not yet placed
    let startAt: Int[] = [-1; 9];
    let queue: Int[] = [];
    let queued: Int = 0;

    // Place initial loads at time 0
    loop i in 0..n {
        let p: Int = pref[i];
        if freeAt[p] == 0 {
            freeAt[p] = dur[i];
            startAt[i] = 0;
        } else {
            let placed: Bool = false;
            loop d in 0..3 {
                if !placed && freeAt[d] == 0 {
                    freeAt[d] = dur[i];
                    startAt[i] = 0;
                    placed = true;
                }
            }
            if !placed {
                queue = queue + [i];
                queued = queued + 1;
            }
        }
    }

    // Process queue: repeatedly find earliest dryer free time, free those dryers, place queued loads
    loop {
        if length(queue) == 0 {
            break;
        }
        // Find earliest time a busy dryer frees
        let earliest: Int = -1;
        loop d in 0..3 {
            if freeAt[d] > 0 {
                if earliest == -1 || freeAt[d] < earliest {
                    earliest = freeAt[d];
                }
            }
        }
        if earliest == -1 {
            break;
        }

        // Free all dryers that finish at 'earliest'
        let freeCount: Int = 0;
        loop d in 0..3 {
            if freeAt[d] == earliest {
                freeAt[d] = 0;
                freeCount = freeCount + 1;
            }
        }

        // Try to place queued loads (in order) onto free dryers
        let newQueue: Int[] = [];
        loop qi in 0..length(queue) {
            let li: Int = queue[qi];
            let p: Int = pref[li];
            let placed: Bool = false;
            if freeAt[p] == 0 {
                freeAt[p] = earliest + dur[li];
                startAt[li] = earliest;
                placed = true;
            } else {
                loop d in 0..3 {
                    if !placed && freeAt[d] == 0 {
                        freeAt[d] = earliest + dur[li];
                        startAt[li] = earliest;
                        placed = true;
                    }
                }
            }
            if !placed {
                newQueue = newQueue + [li];
            }
        }
        queue = newQueue;
    }

    // Compute completion times
    let completed: Int[] = [0; 9];
    loop i in 0..n {
        if startAt[i] >= 0 {
            completed[i] = startAt[i] + dur[i];
        }
    }

    let c60: Int = 0;
    let c120: Int = 0;
    let c200: Int = 0;
    loop i in 0..n {
        if completed[i] > 0 && completed[i] <= 60 {
            c60 = c60 + 1;
        }
        if completed[i] > 0 && completed[i] <= 120 {
            c120 = c120 + 1;
        }
        if completed[i] > 0 && completed[i] <= 200 {
            c200 = c200 + 1;
        }
    }

    fx {
        println("LoadsCompletedByTime60=", c60);
        println("LoadsCompletedByTime120=", c120);
        println("LoadsCompletedByTime200=", c200);
        println("LoadsQueued=", queued);
    }
    ret;
}

fn main() -> Void {
    let directions: Text[] = ["I", "O", "I", "O", "I", "O", "I", "O", "I", "O"];
    let counts: Int[] = [3, 1, 5, 2, 4, 6, 2, 3, 7, 4];
    let capacity: Int = 20;
    let carsInLot: Int = 0;
    let carsTurnedAway: Int = 0;
    let peakOccupancy: Int = 0;

    loop i in 0..length(directions) {
        let dir: Text = directions[i];
        let count: Int = counts[i];
        if dir == "I" {
            let free: Int = capacity - carsInLot;
            let admitted: Int = min(count, free);
            carsInLot = carsInLot + admitted;
            carsTurnedAway = carsTurnedAway + (count - admitted);
            if carsInLot > peakOccupancy {
                peakOccupancy = carsInLot;
            }
        } else {
            carsInLot = carsInLot - count;
        }
    }

    let spacesFree: Int = capacity - carsInLot;

    fx {
        println("CarsInLot=", carsInLot);
        println("CarsTurnedAway=", carsTurnedAway);
        println("PeakOccupancy=", peakOccupancy);
        println("SpacesFree=", spacesFree);
    }
    ret;
}

