fn main() -> Void {
    let zones: Int[] = [0, 0, 0, 0, 0];
    let current: Int = 1;
    zones[0] = zones[0] + 1;

    let targets: Int[] = [3, 5, 2, 4, 1];

    loop t in targets {
        if t > current {
            loop z in current + 1..t + 1 {
                zones[z - 1] = zones[z - 1] + 1;
            }
        } else if t < current {
            loop z in t..current {
                zones[z - 1] = zones[z - 1] + 1;
            }
        }
        current = t;
    }

    fx {
        println("Zone 1: ", zones[0]);
        println("Zone 2: ", zones[1]);
        println("Zone 3: ", zones[2]);
        println("Zone 4: ", zones[3]);
        println("Zone 5: ", zones[4]);
    }
    ret;
}

