    let longestRun: Int = 0;
    let currentRun: Int = 0;
    loop i in 0..n {
        if ratings[i] >= 4 {
            currentRun = currentRun + 1;
            if currentRun > longestRun {
                longestRun = currentRun;
            }
        } else {
            currentRun = 0;
        }
    }

    // 2. Number of adjacent pairs where rating increases
    let increasingPairs: Int = 0;
    loop i in 0..n - 1 {
        if ratings[i + 1] > ratings[i] {
            increasingPairs = increasingPairs + 1;
        }
    }

    // 3. Index of first stall rated 2
    let firstTwo: Int = -1;
    loop i in 0..n {
        if ratings[i] == 2 {
            firstTwo = i;
            break;
        }
    }

    // 4. Index of last stall rated 5
    let lastFive: Int = -1;
    loop i in 0..n {
        if ratings[i] == 5 {
            lastFive = i;
        }
    }

    // 5. Number of windows of exactly 4 consecutive stalls where every stall is rated at least 3
    let windows4: Int = 0;
    loop i in 0..n - 3 {
        let ok: Bool = true;
        loop j in 0..4 {
            if ratings[i + j] < 3 {
                ok = false;
                break;
            }
        }
        if ok {
            windows4 = windows4 + 1;
        }
    }

    // 6. Number of adjacent pairs where ratings differ by at least 2
    let diffPairs: Int = 0;
    loop i in 0..n - 1 {
        let d: Int = ratings[i + 1] - ratings[i];
