fn main() -> Void {
    let names: Text[] = ["A", "B", "C", "D"];
    let scores: Int[] = [12, 30, 18, 30];
    let n: Int = length(names);

    let order: Int[] = [];
    loop i in 0..n {
        order = order + [i];
    }

    loop i in 0..n {
        loop j in 0..n - 1 - i {
            let a: Int = order[j];
            let b: Int = order[j + 1];
            if scores[a] < scores[b] {
                order[j] = b;
                order[j + 1] = a;
            }
        }
    }

    let winner: Text = names[order[0]];
    let loser: Text = names[order[n - 1]];
    let highest: Int = scores[order[0]];
    let lowest: Int = scores[order[n - 1]];
    let margin: Int = highest - lowest;

    let tied: Bool = false;
    loop i in 0..n {
        loop j in i + 1..n {
            if scores[i] == scores[j] {
                tied = true;
            }
        }
    }

    let sortedNames: Text[] = [];
    loop i in 0..n {
        sortedNames = sortedNames + [names[order[i]]];
    }

    let sortedLine: Text = join(sortedNames, " ");
    let tiedText: Text = if tied { "Yes" } else { "No" };

    fx {
        println("Winner: ", winner);
        println("Margin: ", margin);
        println("Sorted: ", sortedLine);
        println("Tied: ", tiedText);
        println("Loser: ", loser);
    }
    ret;
}

fn main() -> Void {
