fn main() -> Void {
    let nums: Int[] = [1, 2, 3, 4, 5, 6, 7, 8, 9];
    let times: Int[] = [25, 40, 15, 40, 8, 33, 15, 50, 8];
    let n: Int = length(nums);

    loop i in 0..n - 1 {
        let minIdx: Int = i;
        loop j in i + 1..n {
            if times[j] < times[minIdx] {
                minIdx = j;
            }
            if times[j] == times[minIdx] && nums[j] < nums[minIdx] {
                minIdx = j;
            }
        }
        if minIdx != i {
            let tmpN: Int = nums[i];
            nums[i] = nums[minIdx];
            nums[minIdx] = tmpN;
            let tmpT: Int = times[i];
            times[i] = times[minIdx];
            times[minIdx] = tmpT;
        }
    }

    let firstReady: Int = nums[0];
    let longest: Int = 0;
    let totalWait: Int = 0;
    loop i in 0..n {
        if times[i] > longest {
            longest = times[i];
        }
        totalWait = totalWait + times[i];
    }

    let distinctTimes: Int[] = [];
    loop i in 0..n {
        let found: Bool = false;
        loop d in distinctTimes {
            if d == times[i] {
                found = true;
                break;
            }
        }
        if !found {
            distinctTimes = distinctTimes + [times[i]];
        }
    }

    let ties: Int = 0;
    loop t in distinctTimes {
        let cnt: Int = 0;
        loop i in 0..n {
            if times[i] == t {
                cnt = cnt + 1;
            }
        }
        if cnt > 1 {
            ties = ties + 1;
        }
    }

    fx {
        let line1: Text = "Sorted: ";
        loop i in 0..n {
            if i > 0 {
                line1 = line1 + " ";
            }
            line1 = line1 + int_to_text(nums[i]);
        }
        println(line1);
        println("FirstReady: ", firstReady);
        println("Longest: ", longest);
        println("TotalWait: ", totalWait);
        println("Ties: ", ties);
    }
    ret;
}

