type Car {
    id: Text = "";
    length: Int = 0;
    index: Int = 0;
}

@pure
fn compareCars(a: Car, b: Car) -> Int {
    if a.length < b.length {
        ret -1;
    }
    if a.length > b.length {
        ret 1;
    }
    if a.index < b.index {
        ret -1;
    }
    if a.index > b.index {
        ret 1;
    }
    ret 0;
}

@pure
fn sortCars(cars: Car[]) -> Car[] {
    let n: Int = length(cars);
    let sorted: Car[] = cars;
    loop i in 1..n {
        let key: Car = sorted[i];
        let j: Int = i - 1;
        loop j >= 0 && compareCars(sorted[j], key) > 0 {
            sorted[j + 1] = sorted[j];
            j = j - 1;
        }
        sorted[j + 1] = key;
    }
    ret sorted;
}

