    let unassigned: Int = 0;
    let longestTask: Text = "";
    let longestHours: Real = -1.0;
    let monthCounts: Int[] = [0; 13];
    let totalSeverity: Int = 0;

    let crewNames: Text[] = [];
    let crewHours: Real[] = [];

