        let task: Text = toon_get_text_or(row, "task", "");
        let date: Text = toon_get_text_or(row, "date", "");
        let hours: Real = toon_get_real_or(row, "hours", 0.0);
        let severity: Int = toon_get_int_or(row, "severity", 0);

        if severity == 5 && criticalTask == "" {
            criticalTask = task;
        }

        if !toon_has_key(row, "crew") {
            unassigned = unassigned + 1;
        } else {
            let crew: Text = toon_get_text_or(row, "crew", "");
            let idx: Int = index_of(crewNames, crew);
            if idx == -1 {
                crewNames = crewNames + [crew];
                crewHours = crewHours + [hours];
            } else {
                crewHours[idx] = crewHours[idx] + hours;
            }
        }

        if hours > longestHours {
            longestHours = hours;
            longestTask = task;
        }

        if string_len(date) >= 7 {
            let mm: Text = date[5..7];
            let m: Int = parse_int(mm);
            if m >= 1 && m <= 12 {
                monthCounts[m] = monthCounts[m] + 1;
            }
        }

        totalSeverity = totalSeverity + severity;
    }

    let bestCrew: Text = "";
    let bestCrewHours: Real = -1.0;
