        if crewHours[i] > bestCrewHours {
            bestCrewHours = crewHours[i];
            bestCrew = crewNames[i];
        }
    }

    let bestMonth: Int = 1;
    let bestMonthCount: Int = -1;
    loop m in 1..13 {
        if monthCounts[m] > bestMonthCount {
            bestMonthCount = monthCounts[m];
            bestMonth = m;
        }
    }

    let avgSeverity: Real = 0.0;
    if count > 0 {
        avgSeverity = totalSeverity * 1.0 / count;
    }

    fx {
        println("TASKS: ", count);
        println("CRITICAL: ", criticalTask);
        println("UNASSIGNED: ", unassigned);
        println("LONGEST: ", longestTask, " - ", format_float(longestHours, 1));
