        let total: Int = prep + cook;

        if i == 0 {
            fastestTitle = title;
            fastestTotal = total;
            biggestTitle = title;
            biggestServings = servings;
        } else {
            if total < fastestTotal {
                fastestTitle = title;
                fastestTotal = total;
            }
            if servings > biggestServings {
