fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "[{\"day\":\"Mon\",\"minutes\":45,\"calories\":320,\"heartRateAvg\":132.5},{\"day\":\"Tue\",\"minutes\":30,\"calories\":210},{\"day\":\"Wed\",\"minutes\":50,\"calories\":350,\"heartRateAvg\":140.0},{\"day\":\"Thu\",\"minutes\":40,\"calories\":280,\"heartRateAvg\":128.75,\"steps\":5200}]";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let required: Text[] = ["minutes", "calories", "heartRateAvg"];

    loop i in 0..toon_len(root) {
        let entry: ToonNode = toon_at(root, i);
        let day: Text = toon_get_text_or(entry, "day", "?");

        let missing: Text[] = [];
        loop j in 0..length(required) {
            let field: Text = required[j];
            if !toon_has_key(entry, field) {
                missing = missing + [field];
            }
        }

        let extra: Text[] = [];
        if toon_has_key(entry, "steps") {
            extra = extra + ["steps"];
        }

        if length(missing) == 0 && length(extra) == 0 {
            fx { println(day, " OK"); }
        } else if length(missing) > 0 {
            fx { println(day, " MISSING: ", join(missing, ", ")); }
        } else {
            fx { println(day, " EXTRA: ", join(extra, ", ")); }
        }
    }

    toon_close(doc);
    ret;
}

