    let json: Text = "{\"network\": \"Regional Express\", \"stations\": [{\"code\": \"AAA\", \"name\": \"Ashford\", \"platforms\": 3}, {\"code\": \"BBB\", \"name\": \"Bridgeway\", \"platforms\": 2}, {\"code\": \"CCC\", \"name\": \"Clifton\", \"platforms\": 4}, {\"code\": \"DDD\", \"name\": \"Dunmore\", \"platforms\": 1}], \"routes\": [{\"from\": \"AAA\", \"to\": \"BBB\", \"minutes\": 45}, {\"from\": \"BBB\", \"to\": \"CCC\", \"minutes\": 30}, {\"from\": \"AAA\", \"to\": \"CCC\", \"minutes\": 90}, {\"from\": \"CCC\", \"to\": \"DDD\", \"minutes\": 25}]}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let network: Text = toon_get_text_or(root, "network", "");
    let stations: ToonNode = toon_key(root, "stations");
    let routes: ToonNode = toon_key(root, "routes");

    let stationCount: Int = toon_len(stations);
    let platformTotal: Int = 0;
    loop i in 0..stationCount {
        let st: ToonNode = toon_at(stations, i);
        platformTotal = platformTotal + toon_get_int_or(st, "platforms", 0);
    }

    let routeCount: Int = toon_len(routes);
    let shortest: Int = 0;
    let longest: Int = 0;
    let minutesSum: Int = 0;
    let hasDunmore: Bool = false;

    if routeCount > 0 {
        let first: ToonNode = toon_at(routes, 0);
        shortest = toon_get_int_or(first, "minutes", 0);
        longest = shortest;
        minutesSum = shortest;
        if toon_get_text_or(first, "from", "") == "DDD" || toon_get_text_or(first, "to", "") == "DDD" {
            hasDunmore = true;
        }
    }

    loop i in 1..routeCount {
        let r: ToonNode = toon_at(routes, i);
        let mins: Int = toon_get_int_or(r, "minutes", 0);
        minutesSum = minutesSum + mins;
        if mins < shortest {
            shortest = mins;
        }
        if mins > longest {
            longest = mins;
        }
        if toon_get_text_or(r, "from", "") == "DDD" || toon_get_text_or(r, "to", "") == "DDD" {
            hasDunmore = true;
        }
    }

    let avg: Real = 0.0;
    if routeCount > 0 {
        avg = minutesSum * 1.0 / routeCount;
    }

    fx {
        println("NETWORK: ", network);
        println("STATION COUNT: ", stationCount);
        println("PLATFORM TOTAL: ", platformTotal);
        println("ROUTE COUNT: ", routeCount);
        println("SHORTEST ROUTE: ", shortest);
        println("LONGEST ROUTE: ", longest);
        println("AVG ROUTE MINUTES: ", format_float(avg, 1));
        println("HAS DUNMORE ROUTE: ", hasDunmore);
    }

    toon_close(doc);
    ret;
}

