    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let robot: Text = toon_get_text_or(root, "robot", "");
    let gridSize: Int = toon_get_int_or(root, "grid_size", 0);
    let batteryDrain: Real = toon_get_real_or(root, "battery_drain_per_unit", 0.0);
    let waypoints: ToonNode = toon_key(root, "waypoints");
    let wpCount: Int = toon_len(waypoints);

    let validCount: Int = 0;
    let firstLabel: Text = "";
    let lastValidLabel: Text = "";
    let totalDistance: Real = 0.0;
    let prevX: Int = 0;
    let prevY: Int = 0;
    let hasPrev: Bool = false;

    loop i in 0..wpCount {
        let wp: ToonNode = toon_at(waypoints, i);
        let x: Int = toon_get_int_or(wp, "x", 0);
        let y: Int = toon_get_int_or(wp, "y", 0);
        let label: Text = toon_get_text_or(wp, "label", "");

        if i == 0 {
            firstLabel = label;
        }

        if x < gridSize && y < gridSize {
            validCount = validCount + 1;
            lastValidLabel = label;
            if hasPrev {
                let dx: Int = x - prevX;
                let dy: Int = y - prevY;
                let dist: Real = abs(Real(dx)) + abs(Real(dy));
                totalDistance = totalDistance + dist;
            }
            prevX = x;
            prevY = y;
            hasPrev = true;
        }
    }

    let batteryCost: Real = totalDistance * batteryDrain;

    fx {
        println("ROBOT: ", robot);
        println("GRID: ", gridSize, " x ", gridSize);
        println("WAYPOINT COUNT: ", wpCount);
        println("VALID WAYPOINTS: ", validCount);
        println("FIRST LABEL: ", firstLabel);
        println("LAST VALID LABEL: ", lastValidLabel);
        println("TOTAL DISTANCE: ", format_float(totalDistance, 1));
