    let n: Int = toon_len(root);

    fx { println("COUNT ", n); }

    let baseGames: Text[] = [];
    let baseCounts: Int[] = [];
    let topIdx: Int = 0;
    let topRating: Real = 0.0;
    let ratingSum: Real = 0.0;
    let minIdx: Int = -1;
    let minPlayers: Int = 0;

    loop i in 0..n {
        let row: ToonNode = toon_at(root, i);
        let base: Text = toon_get_text_or(row, "base_game", "");
        let rating: Real = toon_get_real_or(row, "rating", 0.0);
        let hasPlayers: Bool = toon_has_key(row, "players");
        let players: Int = 0;
        if hasPlayers {
            players = toon_get_int_or(row, "players", 0);
        }

        let found: Bool = false;
        loop j in 0..length(baseGames) {
            if baseGames[j] == base {
                baseCounts[j] = baseCounts[j] + 1;
                found = true;
            }
        }
        if !found {
            baseGames = baseGames + [base];
            baseCounts = baseCounts + [1];
        }

        if i == 0 || rating > topRating {
            topIdx = i;
            topRating = rating;
        }
        ratingSum = ratingSum + rating;

        if hasPlayers {
            if minIdx == -1 || players < minPlayers {
                minIdx = i;
                minPlayers = players;
            }
        }
    }

