fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("tips.txt"); }

    let count: Int = length(lines);
    let totalCents: Int = 0;
    let cardCents: Int = 0;
    let cashCents: Int = 0;
    let tableCents: Int[] = [0, 0, 0, 0];
    let tableCount: Int[] = [0, 0, 0, 0];
    let largestId: Text = "";
    let largestCents: Int = -1;

    loop i in 0..count {
        let parts: Text[] = split(lines[i], " ");
        let id: Text = parts[0];
        let method: Text = parts[1];
        let amount: Int = parse_int(parts[2]);
        let table: Int = parse_int(parts[3]);

        totalCents = totalCents + amount;
        if method == "card" {
            cardCents = cardCents + amount;
        } else {
            cashCents = cashCents + amount;
        }

        let tIdx: Int = table - 1;
        tableCents[tIdx] = tableCents[tIdx] + amount;
        tableCount[tIdx] = tableCount[tIdx] + 1;

        if amount > largestCents {
            largestCents = amount;
            largestId = id;
        }
    }

    let totalDollars: Real = totalCents * 0.01;
    let cardDollars: Real = cardCents * 0.01;
    let cashDollars: Real = cashCents * 0.01;
    let largestDollars: Real = largestCents * 0.01;

    fx {
        println("Tips: ", count);
        println("Total: $", format_float(totalDollars, 2));
        println("Card total: $", format_float(cardDollars, 2));
        println("Cash total: $", format_float(cashDollars, 2));
        loop t in 0..4 {
            let tDollars: Real = tableCents[t] * 0.01;
            println("Table ", t + 1, ": ", tableCount[t], " tips, $", format_float(tDollars, 2));
        }
        println("Largest tip: ", largestId, " - $", format_float(largestDollars, 2));
    }
    ret;
}

