fn main() -> Void {
    let yogaMats: Int = 10;
    let kettlebells: Int = 6;
    let jumpRopes: Int = 4;

    // 1. remove 3 yoga mats
    yogaMats = yogaMats - 3;
    // 2. add 5 kettlebells
    kettlebells = kettlebells + 5;
    // 3. transfer 2 kettlebells to jump ropes
    kettlebells = kettlebells - 2;
    jumpRopes = jumpRopes + 2;
    // 4. remove 1 jump rope
    jumpRopes = jumpRopes - 1;
    // 5. add 7 yoga mats
    yogaMats = yogaMats + 7;
    // 6. transfer 4 yoga mats to kettlebells
    yogaMats = yogaMats - 4;
    kettlebells = kettlebells + 4;
    // 7. remove 2 kettlebells
    kettlebells = kettlebells - 2;
    // 8. add 2 jump ropes
    jumpRopes = jumpRopes + 2;

    let names: Text[] = ["yoga mats", "kettlebells", "jump ropes"];
    let counts: Int[] = [yogaMats, kettlebells, jumpRopes];

    // Sort by count ascending, then name alphabetically
    let sortedNames: Text[] = [];
    let sortedCounts: Int[] = [];
    loop i in 0..3 {
        let bestIdx: Int = 0;
        loop j in 1..length(counts) {
            if counts[j] < counts[bestIdx] || (counts[j] == counts[bestIdx] && names[j] < names[bestIdx]) {
                bestIdx = j;
            }
        }
        sortedNames = sortedNames + [names[bestIdx]];
        sortedCounts = sortedCounts + [counts[bestIdx]];
        // Remove bestIdx from arrays
        let newNames: Text[] = [];
        let newCounts: Int[] = [];
        loop k in 0..length(counts) {
            if k != bestIdx {
                newNames = newNames + [names[k]];
                newCounts = newCounts + [counts[k]];
            }
        }
        names = newNames;
        counts = newCounts;
    }

    fx {
        loop i in 0..3 {
            println(sortedNames[i], ": ", sortedCounts[i]);
        }
    }
    ret;
}

