type Coin {
    name: Text = "";
    count: Int = 0;
}

fn main() -> Void {
    let coins: Text[] = ["Quarter", "Dime", "Nickel", "Quarter", "Quarter", "Penny", "Dime", "Nickel", "Penny", "Quarter", "Dime", "Penny", "Nickel", "Quarter", "Penny"];
    let q: Int = 0;
    let d: Int = 0;
    let n: Int = 0;
    let p: Int = 0;

    loop c in coins {
        if c == "Quarter" {
            q = q + 1;
        }
        if c == "Dime" {
            d = d + 1;
        }
        if c == "Nickel" {
            n = n + 1;
        }
        if c == "Penny" {
            p = p + 1;
        }
    }

    let list: Coin[] = [
        new Coin { name: "Quarter", count: q },
        new Coin { name: "Dime", count: d },
        new Coin { name: "Nickel", count: n },
        new Coin { name: "Penny", count: p }
    ];

    let sorted: Coin[] = sorted_by_desc(list, "count");

    let out: Coin[] = [];
    loop i in 0..length(sorted) {
        let j: Int = i;
        let k: Int = i + 1;
        while k < length(sorted) && sorted[k].count == sorted[i].count {
            k = k + 1;
        }
        let group: Coin[] = sorted[i..k];
        let sortedGroup: Coin[] = sorted_by(group, "name");
        loop g in sortedGroup {
            out = out + [g];
        }
        i = k - 1;
    }

    fx {
        loop c in out {
            println(c.name, " ", c.count);
        }
    }
    ret;
}

