fn main() -> Void {
    let types: Text[] = ["X", "Y", "X", "Y"];
    let times: Int[] = [2, 3, 1, 2];
    let n: Int = 4;
    let minTime: Int = 999999;
    let ways: Int = 0;

    loop mask in 1..(1 << n) {
        let total: Int = 0;
        let prevType: Text = "";
        let any: Bool = false;
        loop i in 0..n {
            if (mask & (1 << i)) != 0 {
                total = total + times[i];
                if any && types[i] != prevType {
                    total = total + 1;
                }
                prevType = types[i];
                any = true;
            }
        }
        if total < minTime {
            minTime = total;
            ways = 1;
        } else if total == minTime {
            ways = ways + 1;
        }
    }

    fx {
        println("min time: ", minTime);
        println("ways: ", ways);
    }
    ret;
}

