type Region {
    r: Int = 0;
    c: Int = 0;
    ch: Text = "";
    size: Int = 0;
    score: Int = 0;
}

@pure
fn weight(ch: Text) -> Int {
    if ch == "C" {
        ret 3;
    }
    if ch == "S" {
        ret 1;
    }
    ret 2;
}

fn main() -> Void {
    let grid: Text[] = [
        "RCCCCR",
        "CCSSCC",
        "CSSSSC",
        "CSSSSC",
        "CCSSCC",
        "RCCCCR"
    ];
    let visited: Bool[][] = [];
    loop r in 0..6 {
        let row: Bool[] = [false; 6];
        visited = visited + [row];
    }

    let regions: Region[] = [];

    loop r in 0..6 {
        loop c in 0..6 {
            if !visited[r][c] {
                let ch: Text = grid[r][c];
                let size: Int = 0;
                let stack: Int[] = [r * 6 + c];
                visited[r][c] = true;
                loop stack.length() > 0 {
                    let top: Int = stack[stack.length() - 1];
                    stack = stack[..stack.length() - 1];
                    let cr: Int = top div 6;
                    let cc: Int = top % 6;
                    size = size + 1;
                    let dirs: Int[][] = [[-1, 0], [1, 0], [0, -1], [0, 1]];
                    loop d in 0..4 {
                        let nr: Int = cr + dirs[d][0];
                        let nc: Int = cc + dirs[d][1];
                        if nr >= 0 && nr < 6 && nc >= 0 && nc < 6 && !visited[nr][nc] && grid[nr][nc] == ch {
                            visited[nr][nc] = true;
                            stack = stack + [nr * 6 + nc];
                        }
                    }
                }
                let sc: Int = size * weight(ch);
                regions = regions + [new Region { r: r, c: c, ch: ch, size: size, score: sc }];
            }
        }
    }

    let sorted: Region[] = sorted_by_desc(regions, "score");
    let final: Region[] = [];
    loop i in 0..length(sorted) {
        let best: Int = i;
        loop j in i + 1..length(sorted) {
            if sorted[j].score == sorted[best].score {
                if sorted[j].r < sorted[best].r || (sorted[j].r == sorted[best].r && sorted[j].c < sorted[best].c) {
                    best = j;
                }
            }
        }
        let tmp: Region = sorted[i];
        sorted[i] = sorted[best];
        sorted[best] = tmp;
        final = final + [sorted[i]];
    }

    let total: Int = 0;
    loop reg in final {
        total = total + reg.score;
    }

    fx {
        println("REEF REGION SCORES");
        loop i in 0..length(final) {
            println("Region ", i + 1, ": ", final[i].ch, " ", final[i].size, " ", final[i].score);
        }
        println("Total: ", total);
    }
    ret;
}

