fn main() -> Void {
    let grid: Int[][] = [
        [45, 48, 52, 50, 47],
        [44, 46, 55, 53, 49],
        [43, 45, 54, 56, 51],
        [42, 44, 50, 52, 48]
    ];
    let rows: Int = 4;
    let cols: Int = 5;
    let peaks: Int = 0;
    let valleys: Int = 0;
    let climbs: Int[][] = [];
    let maxClimb: Int = 0;
    let maxR: Int = 0;
    let maxC: Int = 0;

    loop r in 0..rows {
        let row: Int[] = [];
        loop c in 0..cols {
            let isPeak: Bool = true;
            let isValley: Bool = true;
            let climb: Int = 0;

            if r > 0 {
                let up: Int = grid[r - 1][c];
                if up >= grid[r][c] {
                    isPeak = false;
                }
                if up <= grid[r][c] {
                    isValley = false;
                }
                if up > grid[r][c] {
                    climb = climb + (up - grid[r][c]);
                }
            }
            if r < rows - 1 {
                let down: Int = grid[r + 1][c];
                if down >= grid[r][c] {
                    isPeak = false;
                }
                if down <= grid[r][c] {
                    isValley = false;
                }
                if down > grid[r][c] {
                    climb = climb + (down - grid[r][c]);
                }
            }
            if c > 0 {
                let left: Int = grid[r][c - 1];
                if left >= grid[r][c] {
                    isPeak = false;
                }
                if left <= grid[r][c] {
                    isValley = false;
                }
                if left > grid[r][c] {
                    climb = climb + (left - grid[r][c]);
                }
            }
            if c < cols - 1 {
                let right: Int = grid[r][c + 1];
                if right >= grid[r][c] {
                    isPeak = false;
                }
                if right <= grid[r][c] {
                    isValley = false;
                }
                if right > grid[r][c] {
                    climb = climb + (right - grid[r][c]);
                }
            }

            if isPeak {
                peaks = peaks + 1;
            }
            if isValley {
                valleys = valleys + 1;
            }
            row = row + [climb];
            if climb > maxClimb {
                maxClimb = climb;
                maxR = r;
                maxC = c;
            }
        }
        climbs = climbs + [row];
    }

    fx {
        println("ELEVATION GRID ANALYSIS");
        println("Peaks: ", peaks);
        println("Valleys: ", valleys);
        loop r in 0..rows {
            let line: Text = "Climb r" + int_to_text(r + 1) + ":";
            loop c in 0..cols {
                let part: Text = " " + int_to_text(climbs[r][c]);
                let full: Text = line + part;
                if c == cols - 1 {
                    println(full);
                } else {
                    line = full;
                }
            }
        }
        println("Max climb: ", maxClimb, " at r ", maxR + 1, " c ", maxC + 1);
    }
    ret;
}

fn checkIsbn(digits: Int[]) -> Bool {
    let sum: Int = 0;
    loop i in 0..12 {
        let d: Int = digits[i];
        if i % 2 == 0 {
            sum = sum + d;
        } else {
            sum = sum + d * 3;
        }
    }
    let check: Int = (10 - (sum % 10)) % 10;
    ret check == digits[12];
}

fn main() -> Void {
    let isbn1: Int[] = [9, 7, 8, 0, 1, 3, 4, 6, 8, 5, 9, 2, 7];
