    let isbn3: Int[] = [9, 7, 8, 1, 2, 3, 4, 5, 6, 7, 8, 9, 3];
    let isbn4: Int[] = [9, 7, 8, 0, 5, 9, 6, 2, 7, 1, 1, 4, 6];
    let isbn5: Int[] = [9, 7, 8, 4, 4, 1, 2, 3, 4, 5, 6, 7, 8];

    let isbns: Int[][] = [isbn1, isbn2, isbn3, isbn4, isbn5];

    loop i in 0..5 {
        let valid: Bool = checkIsbn(isbns[i]);
        let verdict: Text = if valid { "VALID" } else { "INVALID" };
