}

fn main() -> Void {
    let capacities: Int[] = [6, 5, 7, 4];
    let parties: Int[] = [3, 4, 2, 5, 6, 1, 3, 4];
    let occupied: Int[] = [0, 0, 0, 0];
    let turnedAway: Int = 0;
    let currentRoom: Int = 0;

    loop p in 0..length(parties) {
        let size: Int = parties[p];
        let placed: Bool = false;
        loop r in currentRoom..length(capacities) {
            if occupied[r] + size <= capacities[r] {
                occupied[r] = occupied[r] + size;
                currentRoom = r;
                placed = true;
                break;
            }
        }
        if !placed {
            turnedAway = turnedAway + size;
            currentRoom = length(capacities);
        }
    }

    fx {
        loop r in 0..length(capacities) {
            let free: Int = capacities[r] - occupied[r];
            println("Room ", r + 1, ": occupied=", occupied[r], " free=", free);
        }
        println("Turned away: ", turnedAway);
    }
    ret;
}

