    let c: Int[] = [14, 28, 35, 49];

    let aDust: Int = 0;
    let aScaled: Int[] = [];
    loop w in a {
        aScaled = aScaled + [w div divisor];
        aDust = aDust + (w % divisor);
    }

    let bDust: Int = 0;
    let bScaled: Int[] = [];
    loop w in b {
        bScaled = bScaled + [w div divisor];
        bDust = bDust + (w % divisor);
    }

    let cDust: Int = 0;
    let cScaled: Int[] = [];
    loop w in c {
        cScaled = cScaled + [w div divisor];
        cDust = cDust + (w % divisor);
    }

    fx {
        println("Blend A: ", aScaled[0], " ", aScaled[1], " ", aScaled[2], " ", aScaled[3], " dust=", aDust);
        println("Blend B: ", bScaled[0], " ", bScaled[1], " ", bScaled[2], " ", bScaled[3], " dust=", bDust);
        println("Blend C: ", cScaled[0], " ", cScaled[1], " ", cScaled[2], " ", cScaled[3], " dust=", cDust);
    }
    ret;
}

fn to_base5(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let digits: Int[] = [];
    let v: Int = n;
    loop {
        let d: Int = v % 5;
        digits = digits + [d];
        v = v div 5;
        if v == 0 {
            break;
        }
    }
    let result: Text = "";
    loop i in 0..length(digits) {
        let idx: Int = length(digits) - 1 - i;
        result = result + int_to_text(digits[idx]);
    }
    ret result;
}

fn main() -> Void {
    let prices: Int[] = [37, 62, 84, 15, 100];
    loop p in prices {
        let change: Int = 100 - p;
        let base5: Text = to_base5(change);
        fx {
            println("Change ", change, " = ", base5, " (base 5)");
        }
    }
    ret;
}

@pure
fn digitSum(n: Int) -> Int {
    let s: Int = 0;
    let x: Int = n;
    loop {
        if x == 0 {
            break;
        }
        s = s + x % 10;
        x = x div 10;
    }
    ret s;
}

@pure
fn digitalRoot(n: Int) -> Int {
    let r: Int = digitSum(n);
    loop {
        if r < 10 {
            break;
        }
        r = digitSum(r);
    }
    ret r;
}

