@pure
fn is_valid_label(label: Text) -> Bool {
    if string_len(label) != 7 {
        ret false;
    }
    let prefix: Text = label[0..3];
    if prefix != "APP" && prefix != "PEA" && prefix != "PLM" && prefix != "CHY" {
        ret false;
    }
    if label[3] != "-" {
        ret false;
    }
    loop i in 4..7 {
        if !is_digit(label[i]) {
            ret false;
        }
    }
    ret true;
}

fn main() -> Void {
    let labels: Text[] = [
        "APP-104",
        "PEA-092",
        "PLM-17X",
        "CHY-007",
        "PEA-1000",
        "APP-1A3",
        "CHY-345",
        "PLM-042",
        "BAN-210",
        "APP-000"
    ];
    let valid: Int = 0;
    let invalid: Int = 0;
    loop label in labels {
        if is_valid_label(label) {
            valid = valid + 1;
            fx { println(label, " OK"); }
        } else {
            invalid = invalid + 1;
            fx { println(label, " BAD"); }
        }
    }
    fx { println("VALID=", valid, " INVALID=", invalid); }
    ret;
}

fn main() -> Void {
