    let n: Int = length(names);
    let sortedIdx: Int[] = [];
    loop i in 0..n {
        sortedIdx = sortedIdx + [i];
    }
    loop i in 0..n {
        loop j in 0..n - i - 1 {
            let a: Int = sortedIdx[j];
            let b: Int = sortedIdx[j + 1];
            if nums[b] < nums[a] {
                sortedIdx[j] = b;
                sortedIdx[j + 1] = a;
            }
        }
    }
    fx {
        loop pos in 0..n {
            let idx: Int = sortedIdx[pos];
            println(pos + 1, ". ", names[idx], " (", nums[idx], ")");
        }
    }
    ret;
}

@pure
fn classify(bpm: Int) -> Text {
    if bpm < 100 {
        ret "REST";
    }
    if bpm < 140 {
        ret "ZONE2";
    }
    if bpm < 160 {
        ret "ZONE3";
    }
    ret "ZONE4";
}

