fn is_well_formed(note: Text) -> Bool {
    if !starts_with(note, "HIVE-") {
        ret false;
    }
    if string_len(note) < 7 {
        ret false;
    }
    let digit: Text = note[5];
    if !is_digit(digit) {
        ret false;
    }
    if digit == "0" {
        ret false;
    }
    if note[6] != ":" {
        ret false;
    }
    let status: Text = note[7..];
    if status == "CALM" || status == "ACTIVE" || status == "SWARM" {
        ret true;
    }
    ret false;
}

fn main() -> Void {
    let notes: Text[] = [
        "HIVE-3:CALM",
        "HIVE-5:ACTIVE",
        "HIVE-1:SWARM",
        "HIVE-7:CALM",
        "HIVE-2:active",
        "HIVE-9:CALM",
        "HIVE-4:SWARM",
        "HIVE-6:ACTIVE",
        "HIVE-8:CALM",
        "HIVE-0:ACTIVE"
    ];
    let well: Int = 0;
    let malformed: Int = 0;
    fx {
        loop note in notes {
            if is_well_formed(note) {
                well = well + 1;
                println(note, " WELL");
            } else {
                malformed = malformed + 1;
                println(note, " MALFORMED");
            }
        }
        println("WELL=", well);
        println("MALFORMED=", malformed);
    }
    ret;
}

@pure
fn blockFor(seat: Text) -> Text {
    let letter: Text = seat[0..1];
    if letter == "A" || letter == "B" {
        ret "NORTH";
    }
    if letter == "C" || letter == "D" {
        ret "MIDDLE";
    }
    ret "SOUTH";
}

fn main() -> Void {
    let slips: Text[] = [
        "HARRIS|B2",
        "OKAFOR|A1",
        "LINDQVIST|C4",
        "MORAN|D2",
        "PATEL|E3",
        "QUINN|F1",
        "ROSSI|A4"
    ];

    loop slip in slips {
        let pipeIdx: Int = index_of(slip, "|");
        let reader: Text = slip[0..pipeIdx];
        let seat: Text = slip[pipeIdx + 1..];
        let block: Text = blockFor(seat);
        fx {
            println(reader, " -> seat ", seat, " (block ", block, ")");
        }
    }

    fx {
        println("SEATS=", length(slips));
    }
    ret;
}

fn main() -> Void {
    let entries: Text[] = [
        "DAY=0472",
        "DAY=1038",
        "DAY=0095",
        "DAY=7721",
        "DAY=04X2",
        "DAY=9010",
        "DAY=0316",
        "DAY=55"
    ];
    let total: Int = 0;

    loop entry in entries {
        let valid: Bool = false;
        let digitSum: Int = 0;

        if string_len(entry) == 8 && starts_with(entry, "DAY=") {
            valid = true;
            loop i in 4..8 {
                let ch: Text = entry[i];
                if !is_digit(ch) {
                    valid = false;
                    break;
                }
                digitSum = digitSum + (ord(ch) - ord("0"));
            }
        }

        if valid {
            total = total + digitSum;
            if digitSum % 2 == 0 {
                fx { println(entry, " EVEN-SUM"); }
            } else {
                fx { println(entry, " ODD-SUM"); }
            }
        } else {
            fx { println(entry, " INVALID"); }
        }
    }

    fx { println("DIGITSUM=", total); }
    ret;
}

fn main() -> Void {
    let tags: Text[] = ["AP-PL", "PE-PR", "PLM-BL", "CH-FL", "AP-PL", "PEAR-PR", "AP-X", "PLM-BL", "CH-FL"];
    let decoded: Int = 0;
    let skipped: Int = 0;

    loop tag in tags {
        let hyphenCount: Int = count(tag, "-");
        let valid: Bool = false;
        let blossom: Text = "";
        if hyphenCount == 1 {
            let idx: Int = index_of(tag, "-");
            let tree: Text = tag[0..idx];
            blossom = tag[idx + 1..];
            let treeLen: Int = string_len(tree);
            let blossomLen: Int = string_len(blossom);
            if treeLen >= 2 && treeLen <= 4 && blossomLen == 1 {
                let treeOk: Bool = true;
                loop ch in tree {
                    if !(ch >= "A" && ch <= "Z") {
                        treeOk = false;
                        break;
                    }
                }
                let blossomOk: Bool = blossom >= "a" && blossom <= "e";
                if treeOk && blossomOk {
                    valid = true;
                }
            }
        }
        if valid {
            let translated: Text = "";
            if blossom == "a" {
                translated = "BUD";
            } else if blossom == "b" {
                translated = "LEAF";
            } else if blossom == "c" {
                translated = "PETAL";
            } else if blossom == "d" {
                translated = "FRUIT";
            } else if blossom == "e" {
                translated = "SEED";
            }
            decoded = decoded + 1;
            fx {
                println(tag, " -> ", translated);
            }
        } else {
            skipped = skipped + 1;
            fx {
                println(tag, " SKIP");
            }
        }
    }

    fx {
        println("DECODED=", decoded);
        println("SKIPPED=", skipped);
    }
    ret;
}

